// Config plugin: keeps the app data out of Android backups and device-to-device transfer (RF-088,
// E-028). The native settings live here, versioned, because android/ is generated by `prebuild`
// and never edited by hand. The iOS part adds launch code to AppDelegate.swift (T026).
const {
  AndroidConfig,
  CodeGenerator,
  withAndroidManifest,
  withAppDelegate,
  withDangerousMod,
} = require("expo/config-plugins");
const { mkdirSync, writeFileSync } = require("node:fs");
const { join } = require("node:path");

// Every backup domain of Android. Listing them all means a new Android version cannot add one
// that slips through: an empty or partial rule file means "back up everything else".
const DOMAINS = [
  "root",
  "file",
  "database",
  "sharedpref",
  "external",
  "device_root",
  "device_file",
  "device_database",
  "device_sharedpref",
];

const XML_FOLDER = "app/src/main/res/xml";
const RULES_NAME = "data_extraction_rules";
const FULL_BACKUP_NAME = "full_backup_content";

const excludes = (indent) =>
  DOMAINS.map(
    (domain) => `${indent}<exclude domain="${domain}" path="."/>\n`,
  ).join("");

// Android 12 and later. A missing <device-transfer> section would mean "transfer everything", even
// with allowBackup="false", so both sections are written.
const dataExtractionRules = () =>
  '<?xml version="1.0" encoding="utf-8"?>\n' +
  "<data-extraction-rules>\n" +
  `  <cloud-backup>\n${excludes("    ")}  </cloud-backup>\n` +
  `  <device-transfer>\n${excludes("    ")}  </device-transfer>\n` +
  "</data-extraction-rules>\n";

// Android 11 and lower ignore the file above and read this one.
const fullBackupContent = () =>
  '<?xml version="1.0" encoding="utf-8"?>\n' +
  `<full-backup-content>\n${excludes("  ")}</full-backup-content>\n`;

// Files are overwritten, not merged, so running prebuild again gives the same output and a stale
// file from an earlier run cannot leave an old rule behind.
function withBackupRuleFiles(config) {
  return withDangerousMod(config, [
    "android",
    (modConfig) => {
      const folder = join(modConfig.modRequest.platformProjectRoot, XML_FOLDER);
      mkdirSync(folder, { recursive: true });
      writeFileSync(join(folder, `${RULES_NAME}.xml`), dataExtractionRules());
      writeFileSync(
        join(folder, `${FULL_BACKUP_NAME}.xml`),
        fullBackupContent(),
      );
      return modConfig;
    },
  ]);
}

// Assigning the attributes replaces any value another plugin set, so there is one of each, ours.
function withBackupAttributes(config) {
  return withAndroidManifest(config, (modConfig) => {
    const application = AndroidConfig.Manifest.getMainApplicationOrThrow(
      modConfig.modResults,
    );
    application.$["android:dataExtractionRules"] = `@xml/${RULES_NAME}`;
    application.$["android:fullBackupContent"] = `@xml/${FULL_BACKUP_NAME}`;
    return modConfig;
  });
}

const IOS_TAG = "with-backup-exclusion-ios";

// The first line of the launch function body in the SDK 58 template, matched whatever the
// indentation. The block goes before it, so it runs before React Native starts.
const IOS_ANCHOR = /^\s*let delegate = ReactNativeDelegate\(\)/;

// Same folder as expo-sqlite's defaultDatabaseDirectory on iOS (documentDirectory + "SQLite"), never
// Library/Caches, which iOS may empty. The folder is created first so a first launch is covered; the
// code deletes nothing. A failed attribute write logs one fixed line (no error, no path: principle 5)
// and goes on: the app must still open.
const IOS_EXCLUSION = [
  "    // Keep the database folder out of iCloud and computer backups (RF-088).",
  "    do {",
  "      var databaseFolder = FileManager.default",
  "        .urls(for: .documentDirectory, in: .userDomainMask)[0]",
  '        .appendingPathComponent("SQLite")',
  "      try FileManager.default.createDirectory(",
  "        at: databaseFolder, withIntermediateDirectories: true)",
  "      var values = URLResourceValues()",
  "      values.isExcludedFromBackup = true",
  "      try databaseFolder.setResourceValues(values)",
  "    } catch {",
  '      NSLog("Backup exclusion of the database folder failed")',
  "    }",
].join("\n");

function mergeIosExclusion(contents) {
  try {
    return CodeGenerator.mergeContents({
      src: contents,
      newSrc: IOS_EXCLUSION,
      tag: IOS_TAG,
      anchor: IOS_ANCHOR,
      offset: 0,
      comment: "//",
    }).contents;
  } catch (error) {
    if (error.code !== "ERR_NO_MATCH") throw error;
    throw new Error(
      "with-backup-exclusion: anchor `let delegate = ReactNativeDelegate()` not found in " +
        "AppDelegate.swift. The SDK template changed; update the plugin.",
    );
  }
}

function withIosExclusion(config) {
  return withAppDelegate(config, (modConfig) => {
    if (modConfig.modResults.language !== "swift") {
      throw new Error(
        "with-backup-exclusion: anchor not found, only AppDelegate.swift is supported, got " +
          `AppDelegate.${modConfig.modResults.language}.`,
      );
    }
    modConfig.modResults.contents = mergeIosExclusion(
      modConfig.modResults.contents,
    );
    return modConfig;
  });
}

module.exports = function withBackupExclusion(config) {
  return withIosExclusion(withBackupAttributes(withBackupRuleFiles(config)));
};
